// STATE
let S = {
  dhikr:      {subhan:0, hamd:0, akbar:0, istighfar:0, wird:0, lan:0, salam:0},
  done:       {},
  checklist:  {},
  date:       td(),
  streak:     0,
  points:     0,
  weekHist:   {},
  pomSess:    0,
  fontScale:  1,
  darkMode:   false,
  athanOn:    true,
  reciter:    0,
  khatDay:    1,
  khatDone:   {},
  reminders:  {morning:'07:00', evening:'17:00', ziyarat:'20:00', sleep:'22:30'}
};

function td() { return new Date().toISOString().slice(0,10); }

function loadS() {
  try {
    const raw = JSON.parse(localStorage.getItem('adhkar_v5') || '{}');
    if (raw.date && raw.date !== td()) {
      S.dhikr     = {subhan:0, hamd:0, akbar:0, istighfar:0, wird:0, lan:0, salam:0};
      S.done      = {};
      S.checklist = {};
      S.date      = td();
      S.streak    = raw.streak || 0;
      S.points    = raw.points || 0;
      S.weekHist  = raw.weekHist || {};
      S.pomSess   = 0;
      S.fontScale = raw.fontScale || 1;
      S.darkMode  = raw.darkMode || false;
      S.athanOn   = raw.athanOn !== undefined ? raw.athanOn : true;
      S.reciter   = raw.reciter || 0;
      S.khatDay   = raw.khatDay || 1;
      S.khatDone  = raw.khatDone || {};
      S.reminders = raw.reminders || S.reminders;
    } else if (raw.date) {
      Object.assign(S, raw);
      S.date = td();
    }
  } catch(e) {}
}

function saveS() { localStorage.setItem('adhkar_v5', JSON.stringify(S)); }

// HERO & CANVAS
function renderCanvas() {
  const cv = document.getElementById('hero-canvas');
  if (!cv) return;
  const ctx = cv.getContext('2d');
  cv.width  = window.innerWidth;
  cv.height = window.innerHeight;
  const stars = Array.from({length:120}, () => ({
    x: Math.random() * cv.width, y: Math.random() * cv.height,
    r: Math.random() * 2, a: Math.random()
  }));
  function draw() {
    ctx.clearRect(0, 0, cv.width, cv.height);
    stars.forEach(s => {
      s.a += (Math.random() - 0.5) * 0.05;
      s.a = Math.max(0.1, Math.min(1, s.a));
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(255,255,255,${s.a})`;
      ctx.fill();
    });
    requestAnimationFrame(draw);
  }
  draw();
}

window.launchApp = function launchApp() {
  const h = document.getElementById('hero');
  const a = document.getElementById('app');
  if (h) h.style.display = 'none';
  if (a) {
    a.classList.remove('hidden');
    a.style.display = 'block';
  }
  window.scrollTo(0, 0);
  try { toast('أهلاً وسهلاً 🌿 بارك الله في يومك'); } catch(e) {}
};

function go(tabId) {
  const h = document.getElementById('hero');
  const a = document.getElementById('app');
  if (h) h.style.display = 'none';
  if (a) {
    a.classList.remove('hidden');
    a.style.display = 'block';
  }

  document.querySelectorAll('.tab-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.tab === tabId);
  });
  document.querySelectorAll('.tab-content').forEach(sec => {
    sec.classList.toggle('active', sec.id === 'tab-' + tabId);
  });
  window.scrollTo(0, 0);
}

function toggleDark() {
  S.darkMode = !S.darkMode;
  saveS();
  applyDark();
}

function applyDark() {
  const btn = document.getElementById('btn-dark');
  if (S.darkMode) {
    document.documentElement.classList.add('dark');
    document.body.classList.add('dark');
    if (btn) btn.textContent = '☀️';
  } else {
    document.documentElement.classList.remove('dark');
    document.body.classList.remove('dark');
    if (btn) btn.textContent = '🌙';
  }
}

function chFont(scale) {
  S.fontScale = Math.max(0.8, Math.min(1.4, (S.fontScale || 1) + (scale * 0.1)));
  saveS();
  applyFontScale();
}

function applyFontScale() {
  document.documentElement.style.fontSize = (16 * (S.fontScale || 1)) + 'px';
}

