// DHIKR COUNTERS
function restoreDhikrs() {
  ['subhan','hamd','akbar','istighfar'].forEach(k => {
    const max = k==='akbar'?34:k==='istighfar'?100:33;
    refreshCounter(k, max);
    if ((S.dhikr[k]||0) >= max) markDhikrDone(k);
  });
  setEl('cnt-lan', (S.dhikr.lan||0) + ' / 100');
  setEl('cnt-salam', (S.dhikr.salam||0) + ' / 100');
}

function refreshCounter(k, max) {
  const v = S.dhikr[k] || 0;
  setEl('dn-'+k, v);
  const be = document.getElementById('db-'+k);
  if (be) be.style.width = Math.min(100, (v/max)*100) + '%';
}

function restoreDoneButtons() {
  Object.keys(S.done).forEach(key => {
    document.querySelectorAll(`button.btn-primary[onclick*="'${key}'"]`).forEach(btn => {
      btn.classList.add('done'); btn.textContent = '✅ تمت القراءة';
    });
  });
}

function tapDhikr(k, max) {
  const v = (S.dhikr[k] || 0) + 1;
  if (v > max) return;
  S.dhikr[k] = v;
  saveS();
  const ne = document.getElementById('dn-'+k);
  const be = document.getElementById('db-'+k);
  if (ne) { ne.textContent = v; ne.classList.add('pop'); setTimeout(() => ne.classList.remove('pop'), 130); }
  if (be) be.style.width = Math.min(100, (v/max)*100) + '%';
  if (v >= max) {
    markDhikrDone(k);
    const labels = {subhan:'التسبيح',hamd:'التحميد',akbar:'التكبير',istighfar:'الاستغفار'};
    toast('أحسنت! 🎉 اكتمل ' + (labels[k]||''));
    const ckMap = {subhan:'ck-subhan',hamd:'ck-hamd',akbar:'ck-akbar',istighfar:'ck-istighfar'};
    if (ckMap[k]) { S.checklist[ckMap[k]] = true; saveS(); renderChecklist(); updateStreak(); }
    if (navigator.vibrate) navigator.vibrate([100,50,100]);
  }
}

function markDhikrDone(k) {
  const c = document.getElementById('dc-'+k);
  if (c) c.classList.add('done-card');
  const btn = document.querySelector(`button[onclick="tapDhikr('${k}',${k==='akbar'?34:k==='istighfar'?100:33})"]`);
  if (btn) btn.disabled = true;
}

function resetDhikr(k) {
  S.dhikr[k] = 0; saveS();
  const max = k==='akbar'?34:k==='istighfar'?100:33;
  refreshCounter(k, max);
  const c = document.getElementById('dc-'+k);
  if (c) c.classList.remove('done-card');
  const btn = document.querySelector(`button[onclick="tapDhikr('${k}',${max})"]`);
  if (btn) btn.disabled = false;
}

function tapWird() {
  const v = (S.dhikr.wird || 0) + 1;
  if (v > 100) return;
  S.dhikr.wird = v; saveS();
  const ne = document.getElementById('dn-wird');
  const be = document.getElementById('db-wird');
  if (ne) { ne.textContent = v; ne.classList.add('pop'); setTimeout(()=>ne.classList.remove('pop'),130); }
  if (be) be.style.width = Math.min(100, v) + '%';
  if (v >= 100) {
    toast('أحسنت! 🎉 اكتمل وِرد اليوم');
    S.checklist['ck-wird'] = true; saveS(); renderChecklist(); updateStreak();
  }
}

function resetWird() { S.dhikr.wird = 0; saveS(); refreshCounter('wird', 100); }

function tapLan() {
  const v = (S.dhikr.lan || 0) + 1;
  if (v > 100) return;
  S.dhikr.lan = v; saveS();
  setEl('cnt-lan', v + ' / 100');
  if (v >= 100) toast('أحسنت! اكتمل اللعن ١٠٠ مرة ✨');
}

function tapSalam() {
  const v = (S.dhikr.salam || 0) + 1;
  if (v > 100) return;
  S.dhikr.salam = v; saveS();
  setEl('cnt-salam', v + ' / 100');
  if (v >= 100) {
    S.checklist['ck-ashura'] = true; saveS(); renderChecklist(); updateStreak();
    toast('أحسنت! اكتمل السلام ١٠0 مرة ✨');
  }
}

// MARK READ & COPY
function markRead(btn, key, ckKey) {
  if (btn.classList.contains('done')) return;
  btn.classList.add('done'); btn.textContent = '✅ تمت القراءة';
  S.done[key] = true;
  if (ckKey) { S.checklist[ckKey] = true; }
  saveS(); renderChecklist(); updateStreak();
  toast('بارك الله فيك! ✨');
}

function copyCard(btn) {
  const card = btn.closest('.ayah-card,.duaa-card,.card,.ashura-duaa,.ziyarat-card');
  let text = '';
  if (card) {
    const t = card.querySelector('.ayah-text,.duaa-text,.arabic,.ashura-duaa-text,.ziyarat-text');
    if (t) text = t.innerText;
  }
  if (!text) text = 'جارٍ النسخ...';
  if (navigator.clipboard) { navigator.clipboard.writeText(text).then(() => toast('تم النسخ 📋')).catch(() => fbCopy(text)); }
  else fbCopy(text);
}

function fbCopy(text) {
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.focus();
  ta.select();
  try {
    document.execCommand('copy');
    toast('تم النسخ 📋');
  } catch (e) {
    toast('تعذّر النسخ تلقائياً');
  }
  document.body.removeChild(ta);
}

// POMODORO TIMER
let pomoTimer = null;
let pomoSeconds = 25 * 60;
let pomoMax = 25 * 60;
let pomoisWork = true;

function pomoStart() {
  if (pomoTimer) return;
  const startBtn = document.getElementById('pomo-start');
  const pauseBtn = document.getElementById('pomo-pause');
  if (startBtn) startBtn.style.display = 'none';
  if (pauseBtn) pauseBtn.style.display = 'inline-flex';

  pomoTimer = setInterval(pomoTick, 1000);
}

function pomoPause() {
  if (!pomoTimer) return;
  clearInterval(pomoTimer);
  pomoTimer = null;
  const startBtn = document.getElementById('pomo-start');
  const pauseBtn = document.getElementById('pomo-pause');
  if (startBtn) startBtn.style.display = 'inline-flex';
  if (pauseBtn) pauseBtn.style.display = 'none';
}

function pomoReset() {
  pomoPause();
  pomoisWork = true;
  pomoSeconds = 25 * 60;
  pomoMax = 25 * 60;
  pomoUI();
}

function pomoTick() {
  if (pomoSeconds > 0) {
    pomoSeconds--;
    pomoUI();
  } else {
    pomoPause();
    if (pomoisWork) {
      S.pomSess = (S.pomSess || 0) + 1;
      saveS();
      toast('🎉 أحسنت! انتهت جلسة الدراسة (25 دقيقة). استرح 5 دقائق!');
      pomoisWork = false;
      pomoSeconds = 5 * 60;
      pomoMax = 5 * 60;
    } else {
      toast('🔔 انتهت الاستراحة! استعد لجلسة دراسة جديدة.');
      pomoisWork = true;
      pomoSeconds = 25 * 60;
      pomoMax = 25 * 60;
    }
    pomoUI();
  }
}

function pomoUI() {
  const m = Math.floor(pomoSeconds / 60);
  const s = pomoSeconds % 60;
  const disp = `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
  setEl('pomo-disp', disp);
  setEl('pomo-lbl', pomoisWork ? 'دراسة' : 'استراحة');
  setEl('pomo-sess', 'جلسات اليوم: ' + (S.pomSess || 0));

  const ring = document.getElementById('pomo-ring');
  if (ring) {
    const pct = pomoSeconds / pomoMax;
    const offset = 314 * (1 - pct);
    ring.style.strokeDashoffset = offset;
  }
}

// PRAYER TIMES & ATHAN
let prayerTimes = { fajr: '04:30', dhuhr: '12:15', asr: '15:45', maghrib: '18:30', isha: '20:00' };

function loadPrayerTimes() {
  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(async pos => {
      try {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${lat}&longitude=${lng}&method=4`);
        const data = await res.json();
        if (data && data.data && data.data.timings) {
          const t = data.data.timings;
          prayerTimes = { fajr: t.Fajr, dhuhr: t.Dhuhr, asr: t.Asr, maghrib: t.Maghrib, isha: t.Isha };
        }
      } catch(e) {}
      updatePrayerUI();
    }, () => updatePrayerUI());
  } else {
    updatePrayerUI();
  }
}

function updatePrayerUI() {
  setEl('pt-fajr', prayerTimes.fajr);
  setEl('pt-dhuhr', prayerTimes.dhuhr);
  setEl('pt-asr', prayerTimes.asr);
  setEl('pt-maghrib', prayerTimes.maghrib);
  setEl('pt-isha', prayerTimes.isha);
}

function toggleAthan() {
  S.athanOn = !S.athanOn;
  saveS();
  updateAthanBtn();
  if (S.athanOn) {
    playAthan();
    toast('🔊 تم تفعيل صبيحة الأذان الصوتية');
  } else {
    const audio = document.getElementById('athan-audio');
    if (audio) audio.pause();
    toast('🔇 تم كتم الأذان الصوتي');
  }
}

function updateAthanBtn() {
  const btn = document.getElementById('btn-athan');
  if (btn) {
    btn.textContent = S.athanOn ? '📢 مفعّل' : '🔇 مكتوم';
    btn.style.opacity = S.athanOn ? '1' : '0.6';
  }
}

function playAthan() {
  const audio = document.getElementById('athan-audio');
  if (audio) {
    audio.currentTime = 0;
    audio.play().catch(() => {});
  }
}

// REMINDERS & NOTIFICATIONS – REAL BACKGROUND NOTIFICATIONS
let deferredInstallPrompt = null;

// Catch the PWA install prompt early
window.addEventListener('beforeinstallprompt', e => {
  e.preventDefault();
  deferredInstallPrompt = e;
  const banner = document.getElementById('install-banner');
  if (banner && !localStorage.getItem('adhkar_install_dismissed')) {
    banner.classList.remove('hidden');
  }
});

function triggerPwaInstall() {
  if (deferredInstallPrompt) {
    deferredInstallPrompt.prompt();
    deferredInstallPrompt.userChoice.then(result => {
      if (result.outcome === 'accepted') {
        dismissInstallBanner();
        toast('✅ تم تثبيت أذكاري على شاشتك الرئيسية!');
      }
      deferredInstallPrompt = null;
    });
  } else {
    // iOS – no prompt API, show instructions
    openReminder();
  }
}

function dismissInstallBanner() {
  const banner = document.getElementById('install-banner');
  if (banner) banner.classList.add('hidden');
  localStorage.setItem('adhkar_install_dismissed', '1');
}

function openReminder() {
  // Request permission immediately
  if ('Notification' in window && Notification.permission === 'default') {
    Notification.requestPermission().then(updateNotifStatus);
  }
  // Load saved values
  const rem = S.reminders || { morning:'07:00', evening:'17:00', ziyarat:'20:00', sleep:'22:30' };
  const m = document.getElementById('rt-morning');   if (m) m.value = rem.morning;
  const e = document.getElementById('rt-evening');   if (e) e.value = rem.evening;
  const z = document.getElementById('rt-ziyarat');   if (z) z.value = rem.ziyarat;
  const s = document.getElementById('rt-sleep');     if (s) s.value = rem.sleep;

  const chk = document.getElementById('chk-athan-alert');
  if (chk) chk.checked = !!(S.athanAlert);

  const wt = document.getElementById('wird-custom-text');
  const wtime = document.getElementById('wird-custom-time');
  if (wt) wt.value = (S.customWird && S.customWird.text) || '';
  if (wtime) wtime.value = (S.customWird && S.customWird.time) || '08:00';

  updateNotifStatus();

  const el = document.getElementById('reminder-overlay');
  if (el) el.classList.remove('hidden');
}

function closeReminder() {
  const el = document.getElementById('reminder-overlay');
  if (el) el.classList.add('hidden');
}

function updateNotifStatus() {
  const el = document.getElementById('notif-perm-status');
  const msg = document.getElementById('notif-status-msg');
  if (!el) return;
  if (!('Notification' in window)) {
    el.innerHTML = '⚠️ متصفحك لا يدعم الإشعارات';
    el.className = 'notif-perm-status notif-warn';
    return;
  }
  const p = Notification.permission;
  if (p === 'granted') {
    el.innerHTML = '✅ الإشعارات مفعّلة – ستصلك حتى لو أغلقت التطبيق (عند التثبيت)';
    el.className = 'notif-perm-status notif-ok';
    if (msg) msg.textContent = 'الإشعارات مفعّلة بنجاح 🔔';
  } else if (p === 'denied') {
    el.innerHTML = '❌ الإشعارات محظورة – يرجى السماح من إعدادات المتصفح';
    el.className = 'notif-perm-status notif-err';
    if (msg) msg.textContent = 'يرجى السماح بالإشعارات من الإعدادات';
  } else {
    el.innerHTML = '⏳ لم يُسمح بالإشعارات بعد – اضغط "تفعيل" أدناه';
    el.className = 'notif-perm-status notif-warn';
  }
}

async function saveReminders() {
  const m = document.getElementById('rt-morning');
  const e = document.getElementById('rt-evening');
  const z = document.getElementById('rt-ziyarat');
  const s = document.getElementById('rt-sleep');
  const chk = document.getElementById('chk-athan-alert');
  const wt = document.getElementById('wird-custom-text');
  const wtime = document.getElementById('wird-custom-time');

  S.reminders = {
    morning: m ? m.value : '07:00',
    evening: e ? e.value : '17:00',
    ziyarat: z ? z.value : '20:00',
    sleep:   s ? s.value : '22:30',
  };
  S.athanAlert = chk ? chk.checked : false;
  S.customWird = {
    text: wt ? wt.value.trim() : '',
    time: wtime ? wtime.value : '08:00',
  };
  saveS();

  // طلب الإذن
  if ('Notification' in window && Notification.permission !== 'granted') {
    try { await Notification.requestPermission(); } catch(err) {}
  }

  // تفعيل Periodic Background Sync (Android Chrome)
  if ('serviceWorker' in navigator && 'PeriodicSyncManager' in window) {
    try {
      const reg = await navigator.serviceWorker.ready;
      const tags = await reg.periodicSync.getTags();
      if (!tags.includes('adhkar-check')) {
        await reg.periodicSync.register('adhkar-check', { minInterval: 60 * 1000 }); // كل دقيقة كحد أدنى
      }
    } catch (e) {
      // Periodic Sync غير مدعوم – الـ SW يتحقق عند فتح التطبيق
    }
  }

  // إرسال الجدول للـ Service Worker
  await pushScheduleToSW();

  closeReminder();
  updateNotifStatus();
  toast('🔔 تم حفظ وتفعيل الإشعارات بنجاح!');
}

async function pushScheduleToSW() {
  if (!('serviceWorker' in navigator)) return;
  try {
    const reg = await navigator.serviceWorker.ready;
    if (!reg.active) return;
    const channel = new MessageChannel();
    reg.active.postMessage({
      type: 'SCHEDULE_NOTIFS',
      schedule: {
        morning:    S.reminders && S.reminders.morning,
        evening:    S.reminders && S.reminders.evening,
        ziyarat:    S.reminders && S.reminders.ziyarat,
        sleep:      S.reminders && S.reminders.sleep,
        athanAlert: S.athanAlert,
        prayers:    prayerTimes,
        wird: S.customWird || {},
      }
    }, [channel.port2]);
  } catch(e) {}
}

async function testNotif() {
  if (!('Notification' in window)) {
    toast('متصفحك لا يدعم الإشعارات');
    return;
  }
  let perm = Notification.permission;
  if (perm === 'default') {
    try { perm = await Notification.requestPermission(); } catch(e) {}
  }
  if (perm === 'granted') {
    await sendNotif('أذكاري 🌿', 'هذا إشعار تجريبي! الإشعارات تعمل بنجاح ✨', 'test');
    toast('✅ تم إرسال الإشعار التجريبي');
    updateNotifStatus();
  } else {
    toast('❌ يرجى السماح بالإشعارات من إعدادات الجهاز');
  }
}

let lastNotifMin = '';
function checkReminders() {
  // يشتغل لما يكون التطبيق مفتوح (backup للـ SW)
  const now = new Date();
  const timeStr = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
  if (timeStr === lastNotifMin) return;

  const rem = S.reminders || {};
  const CHECKS = [
    { key: 'morning', time: rem.morning, title:'أذكار الصباح 🌅', body:'حان وقت أذكار الصباح، ابدأ يومك بذكر الله!' },
    { key: 'evening', time: rem.evening, title:'أذكار المساء 🌇', body:'حان وقت أذكار المساء، حصّن نفسك بذكر الله!' },
    { key: 'ziyarat', time: rem.ziyarat, title:'زيارة عاشوراء 🏴', body:'حان وقت زيارة عاشوراء والأدعية المباركة.' },
    { key: 'sleep',   time: rem.sleep,   title:'أذكار النوم 🌙', body:'حان وقت أذكار النوم وآية الكرسي.' },
  ];

  // تنبيه الأذان – 5 دقائق قبل
  if (S.athanAlert && prayerTimes) {
    const prayers = ['fajr','dhuhr','asr','maghrib','isha'];
    const names = {fajr:'الفجر',dhuhr:'الظهر',asr:'العصر',maghrib:'المغرب',isha:'العشاء'};
    prayers.forEach(p => {
      if (prayerTimes[p]) {
        const pt = prayerTimes[p];
        const parts = pt.split(':');
        let h = parseInt(parts[0],10), mn = parseInt(parts[1],10) - 5;
        if (mn < 0) { mn += 60; h -= 1; }
        if (h < 0) h += 24;
        const alertTime = `${String(h).padStart(2,'0')}:${String(mn).padStart(2,'0')}`;
        CHECKS.push({ key: 'athan_'+p, time: alertTime, title:`تنبيه ${names[p]} 🕌`, body:`صلاة ${names[p]} بعد 5 دقائق، استعد للصلاة 🤲` });
      }
    });
  }

  // الورد المخصص
  if (S.customWird && S.customWird.text && S.customWird.time) {
    CHECKS.push({ key:'custom_wird', time: S.customWird.time, title:'📿 وردك اليومي', body: S.customWird.text });
  }

  for (const c of CHECKS) {
    if (c.time && timeStr === c.time) {
      lastNotifMin = timeStr;
      sendNotif(c.title, c.body, c.key);
      break;
    }
  }
}

async function sendNotif(title, body, tag) {
  toast(`🔔 ${title}`);
  if ('Notification' in window && Notification.permission === 'granted') {
    if ('serviceWorker' in navigator) {
      try {
        const reg = await navigator.serviceWorker.ready;
        if (reg && reg.showNotification) {
          await reg.showNotification(title, {
            body,
            dir: 'rtl', lang: 'ar',
            vibrate: [200, 100, 200],
            tag: tag || 'adhkar',
            icon: `data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='20' fill='%230d6e4f'/><text y='72' x='50' text-anchor='middle' font-size='60' fill='%23fbbf24'>&#x262a;</text></svg>`,
            badge: `data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='20' fill='%230d6e4f'/><text y='72' x='50' text-anchor='middle' font-size='60' fill='%23fbbf24'>&#x262a;</text></svg>`,
            data: { url: './' }
          });
          return;
        }
      } catch (e) {}
    }
    try { new Notification(title, { body, icon: '', dir: 'rtl', lang: 'ar' }); } catch(e) {}
  }
}

// TASBIH MODAL
let tasbihWord = 'سُبْحَانَ اللَّهِ';
let tasbihMax = 33;
let tasbihCount = 0;

function openTasbih() {
  const el = document.getElementById('tasbih-overlay');
  if (el) el.classList.remove('hidden');
}

function closeTasbih() {
  const el = document.getElementById('tasbih-overlay');
  if (el) el.classList.add('hidden');
}

function setTasbih(btn, w, max) {
  if (btn && btn.tagName) {
    document.querySelectorAll('.tasbih-chip').forEach(c => c.classList.remove('on'));
    btn.classList.add('on');
  }
  tasbihWord = w;
  tasbihMax = max;
  tasbihCount = 0;
  setEl('tb-word', w);
  setEl('tb-of', 'من ' + max);
  setEl('tb-num', '0');
  const bar = document.getElementById('tb-prog');
  if (bar) bar.style.width = '0%';
}

function tapTasbih() {
  if (tasbihCount < tasbihMax) {
    tasbihCount++;
    setEl('tb-num', tasbihCount);
    const bar = document.getElementById('tb-prog');
    if (bar) bar.style.width = (tasbihCount / tasbihMax * 100) + '%';
    if (navigator.vibrate) navigator.vibrate(40);
    if (tasbihCount >= tasbihMax) {
      toast('🎉 اكتمل التسبيح (' + tasbihWord + ')');
      if (navigator.vibrate) navigator.vibrate([100,50,100]);
    }
  }
}

function resetTasbih() {
  tasbihCount = 0;
  setEl('tb-num', '0');
  const bar = document.getElementById('tb-prog');
  if (bar) bar.style.width = '0%';
}

